'use strict';
const DATA=JSON.parse(document.getElementById('question-data').textContent), CONCEPTS=JSON.parse(document.getElementById('concept-data').textContent);
const Q=new Map(DATA.map(q=>[q.id,q])), C=new Map(CONCEPTS.map(c=>[c.id,c]));
const SUBJECTS=['','데이터 이해','데이터 분석 기획','데이터 분석'];
const CATEGORIES={A:'데이터 마이닝·연관분석',B:'회귀·분류',C:'추정·검정',D:'확률분포·기초통계',E:'시계열·전처리',F:'상관·거리',G:'분석 기획·성숙도'};
const KEY='adsp.interactive.v2', SEED_KEY='adsp.public.clean.v1', blank=()=>({schema:2,dataset:'44-50-v1',sessions:[],archivedSessions:[],seedImports:[],active:null,stars:[],concepts:{},theme:'light',timerEnabled:false,bookmark:null});
let state=blank(),storageError='',route='home',searchText='',conceptFilter='',conceptQuery='',conceptFav=false,subjectFilter=0,currentConcept=null,listPage=0,toastId;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=s=>new DOMParser().parseFromString(s,'text/html').body.textContent||'';
const icons={star:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m12 3 2.8 5.8 6.4.9-4.6 4.5 1.1 6.3-5.7-3-5.7 3 1.1-6.3-4.6-4.5 6.4-.9Z"/></svg>',download:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 3v12m-4-4 4 4 4-4M5 16v4h14v-4"/></svg>',moon:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 15A9 9 0 0 1 9 4a9 9 0 1 0 11 11Z"/></svg>',sun:'☀'};
const btn=(label,action,data='',secondary=false)=>`<button class="btn ${secondary?'secondary':''}" data-action="${action}" ${data}>${label}</button>`;
const empty=t=>`<div class="card empty">${t}</div>`;
const pct=(a,b)=>b?Math.round(a/b*100):0;
const progress=(a,b)=>`<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="${b}" aria-valuenow="${a}" aria-label="학습 진행률"><span style="width:${pct(a,b)}%"></span></div>`;
function validate(raw){
 if(!raw||raw.schema!==2||!Array.isArray(raw.sessions)||raw.sessions.length+(Array.isArray(raw.archivedSessions)?raw.archivedSessions.length:0)>3000)throw Error('지원하지 않는 학습 기록 형식입니다.');
 const clean=blank();clean.theme=raw.theme==='dark'?'dark':'light';clean.timerEnabled=!!raw.timerEnabled;
 clean.stars=[...new Set((Array.isArray(raw.stars)?raw.stars:[]).filter(x=>Q.has(x)))];
 clean.seedImports=[...new Set((Array.isArray(raw.seedImports)?raw.seedImports:[]).filter(v=>typeof v==='string'&&v.length<100))];
 const seen=new Set(),activeIds=new Set(raw.sessions.map(v=>v.id));
 for(const s of [...raw.sessions,...(Array.isArray(raw.archivedSessions)?raw.archivedSessions:[])]){
  if(typeof s.id!=='string'||s.id.length>100||seen.has(s.id)||!Array.isArray(s.ids)||!s.ids.length||s.ids.length>350||new Set(s.ids).size!==s.ids.length||s.ids.some(id=>!Q.has(id)))throw Error('학습 세트의 문제 목록이 올바르지 않습니다.');
  seen.add(s.id);const answers={};
  for(const id of s.ids){const a=s.answers?.[id];if(a){if(!Number.isInteger(a.selected)||a.selected<1||a.selected>4)throw Error('선택 답안이 올바르지 않습니다.');answers[id]={selected:a.selected,at:Number.isFinite(a.at)?a.at:Date.now()};}}
  const key={};for(const id of s.ids){const v=s.key?.[id]??Q.get(id).answer;if(!Number.isInteger(v)||v<1||v>4)throw Error('정답 데이터가 올바르지 않습니다.');key[id]=v;}
  (activeIds.has(s.id)?clean.sessions:clean.archivedSessions).push({id:s.id,mode:['exam','random','subject','wrong','stars','single','related'].includes(s.mode)?s.mode:'single',title:String(s.title||'학습 세트').slice(0,100),ids:s.ids.slice(),key,answers,index:Math.max(0,Math.min(s.ids.length-1,Number.isInteger(s.index)?s.index:0)),created:Number.isFinite(s.created)?s.created:Date.now(),baseline:s.baseline&&Number.isFinite(s.baseline.total)&&Number.isFinite(s.baseline.correct)?{total:Math.max(0,s.baseline.total),correct:Math.max(0,Math.min(s.baseline.total,s.baseline.correct))}:null,config:s.config&&Array.isArray(s.config.exam)&&Array.isArray(s.config.subject)?{exam:s.config.exam.filter(x=>['44','45','46','47','48','49','50'].includes(x)),subject:s.config.subject.filter(x=>['1','2','3'].includes(x)),count:['10','20','30','50','all','custom'].includes(s.config.count)?s.config.count:'20',custom:String(Math.max(1,Math.min(350,Number(s.config.custom)||20))),priority:['random','wrong','recent','frequent'].includes(s.config.priority)?s.config.priority:'random',exclude:Array.isArray(s.config.exclude)?s.config.exclude.filter(x=>['correct','learned'].includes(x)):[]}:null,timer:{elapsed:Math.max(0,Math.min(1e10,Number(s.timer?.elapsed)||0)),running:false,since:null}});
 }
 if(raw.bookmark&&clean.sessions.some(s=>s.id===raw.bookmark.sessionId)){const bs=clean.sessions.find(s=>s.id===raw.bookmark.sessionId);clean.bookmark={sessionId:bs.id,index:Math.max(0,Math.min(bs.ids.length-1,Number(raw.bookmark.index)||0)),savedAt:Number(raw.bookmark.savedAt)||0};}
 clean.active=clean.sessions.some(s=>s.id===raw.active)?raw.active:null;
 for(const c of CONCEPTS){const v=raw.concepts?.[c.id];if(v)clean.concepts[c.id]={status:[0,1,2].includes(v.status)?v.status:0,favorite:!!v.favorite,views:Math.max(0,Math.min(1e7,Number(v.views)||0)),last:Number(v.last)||0};}
 return clean;
}
try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved));}catch(e){storageError='저장 기록을 읽지 못했습니다. 기존 기록을 덮어쓰지 않도록 자동 저장을 중지했습니다. 내 학습에서 백업 또는 초기화하세요.';}
let preserveBad=!!storageError;
let desktopReady=false;
function storageWarning(message){storageError=message;const e=document.getElementById('storage-warning');e.textContent=message;e.classList.toggle('hidden',!message);}
function persistDesktop(){if(!desktopReady||preserveBad)return;window.adspDesktop.write(JSON.stringify(state)).then(()=>{if(storageError.startsWith('앱 기록 저장'))storageWarning('');}).catch(()=>storageWarning('앱 기록 저장에 실패했습니다. 내 학습에서 JSON 백업을 내려받으세요.'));}
function save(){if(preserveBad)return;try{localStorage.setItem(KEY,JSON.stringify(state));storageError='';}catch(e){if(!desktopReady)storageWarning('브라우저에 저장하지 못했습니다. 새로고침 전에 JSON 백업을 내려받으세요.');}persistDesktop();}

// Import the supplied backup exactly once per browser storage, without replacing existing history.
function mergeBackup(base,incoming){
 const result=validate(JSON.parse(JSON.stringify(base)));let conflicts=0;
 for(const incomingSet of incoming.sessions){
  if(result.archivedSessions.some(s=>s.id===incomingSet.id))continue;
  const existing=result.sessions.find(s=>s.id===incomingSet.id);
  if(!existing){result.sessions.push(incomingSet);continue;}
  if(JSON.stringify(existing.ids)!==JSON.stringify(incomingSet.ids)||existing.ids.some(id=>existing.key[id]!==incomingSet.key[id])){conflicts++;continue;}
  let conflict=false;for(const id of existing.ids){const a=existing.answers[id],b=incomingSet.answers[id];if(a&&b&&a.selected!==b.selected){conflict=true;break;}}
  if(conflict){conflicts++;continue;}
  const oldCount=Object.keys(existing.answers).length,newCount=Object.keys(incomingSet.answers).length;
  for(const [id,a] of Object.entries(incomingSet.answers))if(!existing.answers[id])existing.answers[id]=a;
  if(newCount>oldCount)existing.index=incomingSet.index;
 }
 for(const archived of incoming.archivedSessions)if(!result.sessions.some(s=>s.id===archived.id)&&!result.archivedSessions.some(s=>s.id===archived.id))result.archivedSessions.push(archived);
 result.seedImports=[...new Set([...result.seedImports,...incoming.seedImports])];
 result.stars=[...new Set([...result.stars,...incoming.stars])];
 for(const [id,v] of Object.entries(incoming.concepts)){const old=result.concepts[id];result.concepts[id]=old?{status:Math.max(old.status,v.status),favorite:old.favorite||v.favorite,views:Math.max(old.views,v.views),last:Math.max(old.last,v.last)}:v;}
 if(!result.active&&incoming.active&&result.sessions.some(s=>s.id===incoming.active))result.active=incoming.active;
 if(!result.bookmark&&incoming.bookmark&&result.sessions.some(s=>s.id===incoming.bookmark.sessionId))result.bookmark=incoming.bookmark;
 return {state:result,conflicts};
}
function installEmbeddedBackup(){
 if(preserveBad)return;
 try{
  if(state.seedImports.includes(SEED_KEY)||localStorage.getItem(SEED_KEY))return;
  const saved=localStorage.getItem(KEY),embedded=validate(JSON.parse(document.getElementById('backup-data').textContent));
  const merged=saved?mergeBackup(state,embedded):{state:embedded,conflicts:0};
  state=merged.state;state.seedImports=[...new Set([...state.seedImports,SEED_KEY])];localStorage.setItem(KEY,JSON.stringify(state));localStorage.setItem(SEED_KEY,'installed');
  if(merged.conflicts)storageError=`첨부 기록 중 ${merged.conflicts}개 세트가 기존 기록과 충돌해 기존 세트를 유지했습니다. ZIP의 원본 백업은 보존되어 있습니다.`;
 }catch(e){storageError='첨부된 학습 기록을 자동 반영하지 못했습니다. ZIP에 포함된 JSON 백업을 내 학습에서 가져오세요.';}
}
function toast(msg){const e=document.getElementById('toast');e.textContent=msg;e.classList.remove('hidden');clearTimeout(toastId);toastId=setTimeout(()=>e.classList.add('hidden'),4200);}
function session(){return state.sessions.find(s=>s.id===state.active);}
function answered(s){return Object.keys(s.answers).length;}
function correct(s,subject=0){return s.ids.filter(id=>(!subject||Q.get(id).subject===subject)&&s.answers[id]&&s.answers[id].selected===s.key[id]).length;}
function allSessions(){return [...state.sessions,...state.archivedSessions];}
function stats(ids=null){const map=new Map();for(const s of allSessions())for(const id of s.ids){const a=s.answers[id];if(!a||ids&&!ids.includes(id))continue;let v=map.get(id)||{attempts:0,correct:0,wrong:0,last:0,lastWrong:0,lastCorrect:false};v.attempts++;if(a.selected===s.key[id])v.correct++;else {v.wrong++;v.lastWrong=Math.max(v.lastWrong,a.at);}if(a.at>=v.last){v.last=a.at;v.lastCorrect=a.selected===s.key[id];}map.set(id,v);}return map;}
function summary(){const m=stats();let total=0,right=0;for(const v of m.values()){total+=v.attempts;right+=v.correct;}return {unique:m.size,total,right,rate:pct(right,total)};}
function pauseTimer(){const s=session();if(s?.timer.running){s.timer.elapsed+=Date.now()-s.timer.since;s.timer.running=false;s.timer.since=null;save();}}
let navStack=[],pendingNav=null;
function captureNav(){const ss=session(),form=route==='setup'?document.getElementById('setup-form'):null;const setupFields=form?.elements?Array.from(form.elements).map(e=>({value:e.value,checked:e.checked})):null;return {route,active:state.active,index:ss?.index??0,currentConcept,subjectFilter,searchText,searchExam,searchSubject,conceptFilter,conceptQuery,conceptFav,listPage,setupMode,setupFields};}
function navigate(next){const old=pendingNav||captureNav();pendingNav=null;if(old.route!==next||(next==='concept'&&old.currentConcept!==currentConcept)||(next==='quiz'&&old.active!==state.active)){navStack.push(old);if(navStack.length>100)navStack.shift();}if(route==='quiz'&&next!=='quiz')pauseTimer();route=next;listPage=0;render();window.scrollTo(0,0);}
function goBack(){pendingNav=null;if(route==='quiz')pauseTimer();const old=navStack.pop();if(!old){route='home';render();window.scrollTo(0,0);return;}route=old.route;currentConcept=old.currentConcept;subjectFilter=old.subjectFilter;searchText=old.searchText;searchExam=old.searchExam;searchSubject=old.searchSubject;conceptFilter=old.conceptFilter;conceptQuery=old.conceptQuery;conceptFav=old.conceptFav;listPage=old.listPage;setupMode=old.setupMode;if(old.active&&state.sessions.some(s=>s.id===old.active)){state.active=old.active;if(route==='quiz')session().index=old.index;save();}render();if(route==='setup'&&old.setupFields){const f=document.getElementById('setup-form');Array.from(f.elements).forEach((e,i)=>{const v=old.setupFields[i];if(v){if(e.type==='checkbox'||e.type==='radio')e.checked=v.checked;else if(e.type!=='submit')e.value=v.value;}});poolCount();}window.scrollTo(0,0);}

function createSet(ids,mode,title){pauseTimer();if(!ids.length){toast('조건에 맞는 문제가 없습니다. 필터를 확인하세요.');return;}
 const m=stats(ids);let total=0,good=0;for(const v of m.values()){total+=v.attempts;good+=v.correct;}
 const s={id:'set-'+Date.now()+'-'+Math.random().toString(36).slice(2),mode,title,ids:[...ids],key:Object.fromEntries(ids.map(id=>[id,Q.get(id).answer])),answers:{},index:0,created:Date.now(),baseline:{total,correct:good},timer:{elapsed:0,running:false,since:null}};
 state.sessions.push(s);state.active=s.id;subjectFilter=0;save();navigate('quiz');}
function shuffle(a){a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function related(c){return DATA.map(q=>{const t=(q.plain+' '+plain(q.explanation)).toLowerCase();return {q,rank:c.keywords.reduce((n,k)=>n+(t.includes(k.toLowerCase())?1:0),0)};}).filter(x=>x.rank>0).sort((a,b)=>b.rank-a.rank||a.q.exam-b.q.exam||a.q.no-b.q.no).map(x=>x.q);}
function qConcepts(q){const t=(q.plain+' '+q.options.map(plain).join(' ')).toLowerCase();return CONCEPTS.map(c=>({c,rank:c.keywords.reduce((n,k)=>n+(t.includes(k.toLowerCase())?1:0),0)})).filter(v=>v.rank>0).sort((a,b)=>b.rank-a.rank).slice(0,6).map(v=>v.c);}
function render(){document.body.classList.toggle('dark',state.theme==='dark');document.getElementById('theme').innerHTML=state.theme==='dark'?icons.sun:icons.moon;document.getElementById('theme').setAttribute('aria-label',state.theme==='dark'?'라이트 모드로 전환':'다크 모드로 전환');
 document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.route===(['setup','quiz'].includes(route)?'home':route)));
 const warning=document.getElementById('storage-warning');warning.textContent=storageError;warning.classList.toggle('hidden',!storageError);
 const root=document.getElementById('app');root.innerHTML=(route==='home'?'':'<button class=\"link-btn page-back\" data-action=\"back\">← 뒤로가기</button>')+({home:homeView,setup:setupView,quiz:quizView,search:searchView,stars:starsView,concepts:conceptView,concept:conceptDetail,formulas:formulaView,records:recordsView,help:helpView})[route]?.()||homeView();
 if(route==='quiz')updateTimer();if(route==='concept')drawConcept();document.title=(route==='quiz'?session()?.title+' · ':'')+'ADsP 학습 교재';}
function homeView(){const sum=summary(),m=stats(),s=session();return `<div class="card hero"><div class="eyebrow">ADsP INTERACTIVE BOOK</div><h1>한 문제씩, 확실하게.</h1><p class="muted">44~50회 기출 복원 350문항과 핵심 개념 62개.<br>문제를 풀고, 해설을 읽고, 헷갈린 개념을 연결하세요.</p><div class="pill">ADsP</div>${s?btn('이어서 학습하기 →','resume')+' <span class="small muted">'+esc(s.title)+' · '+answered(s)+'/'+s.ids.length+'</span>':btn('50회부터 시작하기 →','exam','data-exam="50"')}</div>
 <div class="grid stats"><div class="card stat"><strong>${sum.unique}<span> / 350</span></strong><span>풀어본 문제</span>${progress(sum.unique,350)}</div><div class="card stat"><strong>${sum.total?sum.rate+'%':'—'}</strong><span>전체 풀이 정답률 · ${sum.total}번 풀이</span></div><div class="card stat"><strong>${[...m.values()].filter(v=>v.wrong>0).length}</strong><span>다시 볼 오답 · 별표 ${state.stars.length}개</span></div></div>
 <div class="row section-head"><h2>회차별로 풀기</h2><span class="small muted">각 50문항</span></div><div class="grid exam-grid">${[44,45,46,47,48,49,50].map(ex=>{const ids=DATA.filter(q=>q.exam===ex).map(q=>q.id),n=ids.filter(id=>m.has(id)).length;return `<button class="card exam-card" data-action="exam" data-exam="${ex}"><span class="badge">${ex<48?'2025':'2026'} 기출 복원</span><span class="exam-title">제${ex}회 <span class="muted">↗</span></span>${progress(n,50)}<span class="small muted">학습 ${n}/50 · 1·2·3과목</span></button>`;}).join('')}</div>
 ${state.bookmark?`<div class="card row section-head"><div><b>저장한 북마크</b><div class="small muted">${esc(state.sessions.find(v=>v.id===state.bookmark.sessionId)?.title)} · ${state.bookmark.index+1}번째 문항</div></div>${btn('북마크부터 이어서 →','bookmark-resume','',true)}</div>`:''}<h2 class="section-head">원하는 방식으로</h2><div class="grid modes">${[['random','01','전체 랜덤','모든 회차에서 중복 없이 출제'],['subject','02','과목별 랜덤','선택한 과목에 집중'],['wrong','03','오답 집중','틀린 이력을 남기고 다시 학습']].map(([mode,no,title,desc])=>`<button class="card mode" data-action="setup" data-mode="${mode}"><div class="mode-no">MODE ${no}</div><b>${title} →</b><span class="small muted">${desc}</span></button>`).join('')}</div>
 <div class="card row section-head"><div><h3 style="margin-bottom:4px">헷갈린 개념은 바로 정리하기</h3><span class="small muted">공식·비교표·예제와 관련 기출문제를 함께 봅니다.</span></div>${btn('개념 학습관 →','nav','data-to="concepts"',true)}</div><div class="row section-head"><span class="small muted">진도와 풀이 이력은 자동 누적됩니다.</span><button class="link-btn" data-action="reset">전체 학습 기록 초기화</button></div>${footer()}`;}
let setupMode='random';
function setupView(){const mode=setupMode;return `<div class="eyebrow">STUDY SET</div><h1>${{random:'전체 랜덤 출제',subject:'과목별 랜덤 출제',wrong:'오답 집중 학습'}[mode]}</h1><p class="muted">조건을 고르면 출제 순서가 고정된 새 학습 세트를 만듭니다.</p><form id="setup-form" class="card" style="max-width:800px"><fieldset><legend>사용할 회차</legend><div class="checks">${[44,45,46,47,48,49,50].map(ex=>`<label class="check"><input name="exam" type="checkbox" value="${ex}" checked>${ex}회</label>`).join('')}</div></fieldset>
 <fieldset><legend>과목 ${mode==='subject'?'(복수 선택 가능)':''}</legend><div class="checks">${[1,2,3].map(n=>`<label class="check"><input name="subject" type="checkbox" value="${n}" checked>${n}과목 · ${SUBJECTS[n]}</label>`).join('')}</div></fieldset><div class="grid two"><div class="field"><label for="count">문제 수</label><select id="count" name="count"><option>10</option><option selected>20</option><option>30</option><option>50</option><option value="all">전체</option><option value="custom">직접 입력</option></select><input class="hidden" aria-label="직접 입력 문항 수" id="custom-count" name="custom" type="number" min="1" max="350" value="20"></div><div class="field"><label for="priority">출제 순서</label><select id="priority" name="priority"><option value="random">무작위</option><option value="wrong">과거 오답 우선</option><option value="recent">최근 틀린 문제 우선</option><option value="frequent">반복 오답 우선</option></select></div></div><div class="checks">${mode!=='wrong'?`<label class="check"><input type="checkbox" name="exclude" value="correct">최근 맞힌 문제 제외</label><label class="check"><input type="checkbox" name="exclude" value="learned">이미 풀어본 문제 제외</label>`:'<span class="small muted">한 번 맞혀도 과거 오답 이력이 있는 문제는 오답 풀에 남습니다.</span>'}</div><div class="notice" id="pool-count" aria-live="polite"></div><button class="btn" type="submit">새 학습 시작 →</button></form>`;}
function poolFromForm(f){const fd=new FormData(f),ex=fd.getAll('exam').map(Number),subjects=fd.getAll('subject').map(Number),m=stats(),exclude=fd.getAll('exclude');return DATA.filter(q=>ex.includes(q.exam)&&subjects.includes(q.subject)&&(setupMode!=='wrong'||(m.get(q.id)?.wrong||0)>0)&&(!exclude.includes('learned')||!m.has(q.id))&&(!exclude.includes('correct')||!m.get(q.id)?.lastCorrect));}
function poolCount(){const f=document.getElementById('setup-form');if(!f)return;const pool=poolFromForm(f),fd=new FormData(f),n=fd.get('count')==='all'?pool.length:Number(fd.get('count')==='custom'?fd.get('custom'):fd.get('count'));document.getElementById('pool-count').textContent=`사용 가능한 문제 ${pool.length}개 · 실제 출제 ${Math.min(pool.length,Math.max(0,n||0))}개${n>pool.length?' (문제 풀 크기로 제한)':''}`;document.getElementById('custom-count').classList.toggle('hidden',fd.get('count')!=='custom');}
function startRandom(f){const fd=new FormData(f);let pool=shuffle(poolFromForm(f)),n=fd.get('count')==='all'?pool.length:Number(fd.get('count')==='custom'?fd.get('custom'):fd.get('count'));if(!Number.isInteger(n)||n<1){toast('문제 수는 1 이상의 정수로 입력하세요.');return;}const m=stats(),priority=fd.get('priority');if(priority!=='random')pool.sort((a,b)=>{let x=m.get(a.id),y=m.get(b.id);if(priority==='recent')return (y?.lastWrong||0)-(x?.lastWrong||0);if(priority==='frequent')return (y?.wrong||0)-(x?.wrong||0);return Number((y?.wrong||0)>0)-Number((x?.wrong||0)>0);});const available=pool.length;createSet(pool.slice(0,n).map(q=>q.id),setupMode,({random:'전체 랜덤',subject:'과목 랜덤',wrong:'오답 집중'})[setupMode]);if(available){session().config={exam:fd.getAll('exam'),subject:fd.getAll('subject'),exclude:fd.getAll('exclude'),count:fd.get('count'),custom:fd.get('custom'),priority:fd.get('priority')};save();}if(n>available&&available)toast(`${available}개 문제로 출제했습니다. 같은 세트에 중복은 없습니다.`);}
function startFromConfig(config){const f=document.createElement('form');for(const [key,raw]of Object.entries(config)){for(const value of Array.isArray(raw)?raw:[raw]){const input=document.createElement('input');input.name=key;input.value=String(value);f.append(input);}}startRandom(f);}
function questionHistory(id){const attempts=allSessions().flatMap(ss=>ss.answers[id]?[{sessionId:ss.id,title:ss.title,answer:ss.answers[id],correct:ss.answers[id].selected===ss.key[id],archived:state.archivedSessions.some(a=>a.id===ss.id)}]:[]).sort((a,b)=>a.answer.at-b.answer.at||a.sessionId.localeCompare(b.sessionId));return `<section class="attempt-history" aria-label="이 문제 정오답 이력"><div class="row"><b>이 문제 풀이 이력</b><span class="small muted">${attempts.length}회 · 오래된 순</span></div>${attempts.length?`<ol>${attempts.map((a,i)=>`<li><span class="attempt-outcome ${a.correct?'right':'wrong'}">${i+1}회 · ${a.correct?'✓ 정답':'✕ 오답'}</span><span class="small muted">${esc(new Date(a.answer.at).toLocaleString('ko-KR'))} · ${esc(a.title)}${a.archived?' · 목록에서 삭제한 세트':''}${a.sessionId===state.active?' · 이번 세트':''}</span></li>`).join('')}</ol>`:'<p class="small muted" style="margin:8px 0 0">아직 직접 푼 이력이 없습니다.</p>'}</section>`;}
function archiveSet(id){const item=state.sessions.find(s=>s.id===id);if(!item)return;confirmBox('학습 세트 삭제',`‘${item.title}’을 목록에서 삭제합니다. 문제별 풀이 이력과 누적 성적은 보존되며 아래 삭제한 세트에서 복원할 수 있습니다.`,()=>{pauseTimer();state.sessions=state.sessions.filter(s=>s.id!==id);state.archivedSessions.push(item);if(state.active===id)state.active=state.sessions.at(-1)?.id||null;if(state.bookmark?.sessionId===id)state.bookmark=null;navStack=[];pendingNav=null;save();navigate('records');toast('목록에서 삭제했습니다. 풀이 이력은 보존했습니다.');});}
function restoreSet(id){const ss=state.archivedSessions.find(s=>s.id===id);if(!ss)return;state.archivedSessions=state.archivedSessions.filter(s=>s.id!==id);state.sessions.push(ss);if(!state.active)state.active=id;save();render();toast('학습 세트를 복원했습니다.');}
function quizView(){const s=session();if(!s)return empty('진행 중인 학습이 없습니다. 홈에서 시작하세요.');const q=Q.get(s.ids[s.index]),a=s.answers[q.id],good=a&&a.selected===s.key[q.id],n=answered(s),all=n===s.ids.length,cs=a?qConcepts(q):[];
 return `<div class="row"><div><span class="eyebrow">${esc(s.title)}</span><h1 style="font-size:24px;margin-top:6px">${s.index+1} <span class="muted" style="font-weight:400;font-size:16px">/ ${s.ids.length}문항</span></h1></div><div class="small muted">${n}문항 풀이 · 정답 ${correct(s)} · ${n?pct(correct(s),n):0}% ${btn('같은 문제 다시 풀기','retry','',true)}${['random','subject','wrong'].includes(s.mode)?btn('새 랜덤 세트','reroll','',true):''}</div></div>${progress(n,s.ids.length)}
 ${all?`<div class="notice"><b>학습을 완료했습니다. 정답률 ${pct(correct(s),n)}%</b>${s.mode==='wrong'?`<br>이 문제들의 이전 전체 풀이 정답률: ${s.baseline.total?pct(s.baseline.correct,s.baseline.total)+'%':'기록 없음'} → 이번 재학습: ${pct(correct(s),n)}% (동일 문제 풀, 시도 기준)` :''}<div class="small">${[1,2,3].map(k=>{const ids=s.ids.filter(id=>Q.get(id).subject===k);return ids.length?`${k}과목 ${correct(s,k)}/${ids.length}`:'';}).filter(Boolean).join(' · ')}</div></div>`:''}
 <div class="quiz-layout"><section class="card quiz-card"><div class="timer"><label><input id="timer-enable" type="checkbox" ${state.timerEnabled?'checked':''}> 타이머</label><div id="timer-controls" class="row start ${state.timerEnabled?'':'hidden'}"><strong id="timer-value" class="timer-clock">00:00</strong><button data-action="timer-toggle">${s.timer.running?'일시정지':'시작'}</button><button data-action="timer-reset">초기화</button></div></div>
 <div class="row question-head"><div><span class="q-index">Q${String(q.no).padStart(2,'0')}</span><span class="question-meta">　제${q.exam}회 · ${q.subject}과목</span></div><div class="q-tools"><button class="icon-btn ${state.stars.includes(q.id)?'starred':''}" data-action="star" data-id="${q.id}" aria-label="${state.stars.includes(q.id)?'별표 해제':'별표 저장'}" aria-pressed="${state.stars.includes(q.id)}" title="별표 문제에 저장">${icons.star}</button><button class="icon-btn" data-action="image" data-id="${q.id}" aria-label="이 문제 이미지 다운로드" title="이 문제를 PNG 이미지로 저장">${icons.download}</button></div></div>
 ${questionHistory(q.id)}<div class="q-stem rich">${q.stem}</div><div class="options">${q.options.map((o,i)=>`<button class="option ${a?(i+1===s.key[q.id]?'correct':i+1===a.selected?'wrong':''):''}" data-action="answer" data-selected="${i+1}" ${a?'disabled':''}><span class="number">${i+1}</span><span class="rich">${o}${a&&(i+1===s.key[q.id]||i+1===a.selected)?`<span class="answer-tag">${i+1===s.key[q.id]?'✓ 정답':'✕ 선택한 오답'}</span>`:''}</span></button>`).join('')}</div>
 ${a?`<div class="feedback ${good?'':'incorrect'}" role="status"><h3>${good?'✓ 정답입니다!':'✕ 오답입니다'}</h3><div class="small">정답 ${s.key[q.id]}번</div><div class="rich">${q.options[s.key[q.id]-1]}</div></div><section class="explain"><span class="badge">문어CBT 원문 해설</span><div class="rich">${q.sections.main||q.explanation}</div>${q.sections.wrong?`<details><summary>오답 선택지별 풀이</summary><div class="rich">${q.sections.wrong}</div></details>`:''}${q.sections.extra?`<details><summary>보충 개념</summary><div class="rich">${q.sections.extra}</div></details>`:''}${q.review.length?`<div class="notice"><b>별도 검토 주석 (원문과 구분)</b>${q.review.map(t=>`<p>${esc(t)}</p>`).join('')}</div>`:''}${cs.length?`<h3 style="margin-top:20px">관련 개념</h3><div class="chip-links">${cs.map(c=>`<button data-action="concept" data-id="${c.id}">${esc(c.title)} ↗</button>`).join('')}</div><p class="small muted">키워드로 연결한 추가 학습 콘텐츠입니다.</p>`:''}</section>`:`<p class="small muted" style="margin-top:20px">선택지를 누르면 즉시 채점합니다. 키보드 1~4로 선택할 수 있습니다.</p>`}
 <div class="row start" style="margin-top:20px">${btn('현재 위치 북마크','bookmark','',true)}<span class="small muted">마지막 풀이 위치는 자동 저장됩니다.</span></div><div class="quiz-footer"><button class="btn secondary" data-action="move" data-step="-1" ${s.index===0?'disabled':''}>← 이전</button><span class="small muted" style="align-self:center">${a?'채점 완료':'미풀이'}</span><button class="btn" data-action="move" data-step="1" ${s.index===s.ids.length-1?'disabled':''}>다음 →</button></div></section>
 <aside class="card jump-panel"><b class="small">문항 바로가기</b><div class="subject-tabs">${[0,1,2,3].map(k=>`<button class="${subjectFilter===k?'active':''}" data-action="q-filter" data-subject="${k}">${k?k+'과목':'전체'}</button>`).join('')}</div><div class="jump-grid">${s.ids.map((id,i)=>{const x=Q.get(id),ans=s.answers[id];return !subjectFilter||x.subject===subjectFilter?`<button class="${i===s.index?'current':''} ${ans?(ans.selected===s.key[id]?'done':'missed'):''}" data-action="jump" data-index="${i}" title="제${x.exam}회 ${x.no}번 · ${ans?(ans.selected===s.key[id]?'정답':'오답'):'미풀이'}" aria-label="${i+1}번째 문제 · ${ans?(ans.selected===s.key[id]?'정답':'오답'):'미풀이'}">${i+1}${ans?(ans.selected===s.key[id]?'✓':'×'):''}</button>`:'';}).join('')}</div><p class="small muted">✓ 정답 · × 오답<br>번호는 현재 세트의 순서입니다.</p><div class="small">${[1,2,3].map(k=>{const ids=s.ids.filter(id=>Q.get(id).subject===k),done=ids.filter(id=>s.answers[id]).length;return ids.length?`<div>${k}과목 ${correct(s,k)}/${done} 정답 <span class="muted">(${done}/${ids.length} 풀이)</span></div>`:'';}).join('')}</div></aside></div>${footer()}`;
}
function answer(selected){const s=session(),q=Q.get(s?.ids[s.index]);if(!q||s.answers[q.id])return;s.answers[q.id]={selected,at:Date.now()};save();render();}
function jump(index){const s=session();if(index<0||index>=s.ids.length)return;s.index=index;save();render();document.getElementById('app').scrollIntoView({block:'start'});}
function move(step){const s=session();let i=s.index+step;while(i>=0&&i<s.ids.length&&subjectFilter&&Q.get(s.ids[i]).subject!==subjectFilter)i+=step;if(i>=0&&i<s.ids.length)jump(i);else toast('선택한 과목의 마지막/첫 문항입니다. 다른 과목이나 전체를 선택하세요.');}
function searchView(){statsCache=stats();return `<div class="eyebrow">QUESTION SEARCH</div><h1>문제 찾기</h1><p class="muted">350문항의 본문·선택지·해설에서 단어를 찾습니다. 해설은 답안 선택 후 표시합니다.</p><div class="card"><div class="searchbar"><input type="search" id="question-search" aria-label="전체 문제 검색" placeholder="예: 정상성, Apriori, p-value" value="${esc(searchText)}"><select id="search-exam" aria-label="검색 회차" style="width:auto"><option value="0">모든 회차</option>${[44,45,46,47,48,49,50].map(n=>`<option value="${n}" ${searchExam===n?'selected':''}>${n}회</option>`).join('')}</select><select id="search-subject" aria-label="검색 과목" style="width:auto"><option value="0">모든 과목</option>${[1,2,3].map(n=>`<option value="${n}" ${searchSubject===n?'selected':''}>${n}과목</option>`).join('')}</select></div></div><div id="search-results">${searchResults()}</div>`;}
let searchExam=0,searchSubject=0;
function searchResults(){const words=searchText.toLowerCase().trim().split(/\s+/).filter(Boolean);const results=DATA.filter(q=>(!searchExam||q.exam===searchExam)&&(!searchSubject||q.subject===searchSubject)&&words.every(w=>(q.plain+' '+q.options.map(plain).join(' ')+' '+plain(q.explanation)).toLowerCase().includes(w)));return `<div class="row section-head"><span class="small muted">${results.length}개 결과 · 모든 검색어 포함</span></div><div class="results">${results.slice(0,(listPage+1)*30).map(q=>resultCard(q)).join('')||empty('일치하는 문제가 없습니다.')}</div>${results.length>(listPage+1)*30?`<div style="margin-top:20px">${btn('30개 더 보기','more-search','',true)}</div>`:''}`;}
function resultCard(q){const v=statsCache?.get(q.id);return `<div class="card result"><div class="row"><span class="tag">제${q.exam}회 · ${q.no}번 · ${q.subject}과목</span><button class="icon-btn ${state.stars.includes(q.id)?'starred':''}" data-action="star" data-id="${q.id}" aria-label="${q.id} 별표 ${state.stars.includes(q.id)?'해제':'저장'}" aria-pressed="${state.stars.includes(q.id)}">${icons.star}</button></div><h3>${esc(q.plain.slice(0,240))}${q.plain.length>240?'…':''}</h3><div class="row"><span class="small muted">${v?`풀이 ${v.attempts}회 · 오답 ${v.wrong}회 · 최근 ${v.lastCorrect?'정답':'오답'}`:'아직 풀지 않은 문제'}</span>${btn('문제 풀기 →','single',`data-id="${q.id}"`,true)}</div></div>`;}
let statsCache=null;
function starsView(){statsCache=stats();return `<div class="eyebrow">SAVED QUESTIONS</div><h1>별표 문제 <span class="muted">${state.stars.length}</span></h1><p class="muted">문제 오른쪽 위 별을 누르면 여기에 모입니다. 별표는 정오답 기록과 별도로 유지됩니다.</p><div class="row">${btn('모은 문제 순서대로 풀기','play-stars')}${btn('무작위로 다시 풀기','random-stars','',true)}</div><div class="results">${state.stars.map(id=>resultCard(Q.get(id))).join('')||empty('저장한 문제가 없습니다. 문제의 ☆ 버튼을 눌러보세요.')}</div>`;}
function conceptView(){return `<div class="eyebrow">CONCEPT LIBRARY</div><h1>핵심 개념 학습관</h1><p class="muted">대화에서 다룬 개념을 62개 카드로 정리했습니다. 기출 복원 해설과 구분되는 추가 교육 콘텐츠입니다.</p><div class="card"><div class="searchbar"><input id="concept-search" type="search" aria-label="개념 검색" placeholder="개념명·영문·설명 검색" value="${esc(conceptQuery)}"><select id="concept-category" aria-label="개념 카테고리" style="max-width:240px"><option value="">모든 카테고리</option>${Object.entries(CATEGORIES).map(([k,v])=>`<option value="${k}" ${conceptFilter===k?'selected':''}>${k}. ${v}</option>`).join('')}</select><label class="check"><input type="checkbox" id="concept-fav" ${conceptFav?'checked':''}>즐겨찾기</label></div><div class="small muted" style="margin-top:10px">3과목 A~F · 2과목 G · 학습 완료 ${Object.values(state.concepts).filter(v=>v.status===2).length}/62</div></div><div id="concept-results">${conceptResults()}</div>`;}
function conceptResults(){const list=CONCEPTS.filter(c=>(!conceptFilter||c.category===conceptFilter)&&(!conceptFav||state.concepts[c.id]?.favorite)&&(c.title+' '+c.english+' '+c.easy+' '+c.definition+' '+c.trap).toLowerCase().includes(conceptQuery.toLowerCase()));return `<div class="concept-grid">${list.map(c=>`<button class="card concept-card" data-action="concept" data-id="${c.id}"><span class="badge">${c.category} · ${c.subject}과목</span><h3>${esc(c.title)}</h3><span class="english">${esc(c.english)}</span><p>${esc(c.easy)}</p><span class="small muted">${['○ 미학습','◐ 학습 중','✓ 학습 완료'][state.concepts[c.id]?.status||0]} ${state.concepts[c.id]?.favorite?'· ★':''}</span></button>`).join('')||empty('검색 결과가 없습니다.')}</div>`;}
function openConcept(id){if(!C.has(id))return;currentConcept=id;const v=state.concepts[id]||{status:0,favorite:false,views:0};v.views++;v.last=Date.now();if(v.status===0)v.status=1;state.concepts[id]=v;save();navigate('concept');}
function conceptDetail(){const c=C.get(currentConcept);if(!c)return conceptView();const v=state.concepts[c.id],relatedQs=related(c);return `<div class="concept-body"><div class="row" style="margin-top:22px"><span class="badge">${c.category}. ${CATEGORIES[c.category]} · ${c.subject}과목</span><button class="icon-btn ${v.favorite?'starred':''}" data-action="concept-star" data-id="${c.id}" aria-label="개념 즐겨찾기" aria-pressed="${v.favorite}">${icons.star}</button></div><h1 style="margin-top:15px">${esc(c.title)}</h1><p class="small muted">${esc(c.english)} · 추가 작성한 교육 콘텐츠</p><div class="card"><p style="font-size:19px;font-weight:600">${esc(c.easy)}</p><div class="concept-block"><h3>핵심 정의</h3><p>${esc(c.definition)}</p></div><div class="formula">${esc(c.formula)}</div>${conceptViz(c)}<div class="concept-block"><h3>예시로 이해하기</h3><p>${esc(c.example)}</p></div><div class="concept-block"><h3>시험 포인트</h3><p>${esc(c.exam)}</p></div><div class="notice"><b>혼동 주의</b><p style="margin-bottom:0">${esc(c.trap)}</p></div><div class="row"><label>이해도 <select id="concept-status" style="width:auto;margin-left:8px">${['미학습','학습 중','학습 완료'].map((t,i)=>`<option value="${i}" ${v.status===i?'selected':''}>${t}</option>`).join('')}</select></label><span class="small muted">열람 ${v.views}회 · 자동 저장</span></div></div><h2 class="section-head">관련 기출문제</h2><p class="small muted">본문·해설 키워드로 연결한 ${relatedQs.length}문항입니다. 문제를 푼 뒤 개념을 다시 확인하세요.</p>${relatedQs.length?btn('관련 문제로 학습 세트 만들기','related',`data-id="${c.id}"`):''}<div class="results">${relatedQs.slice(0,8).map(q=>resultCard(q)).join('')||empty('직접 일치하는 기출 키워드가 없습니다. 문제 찾기에서 검색해 보세요.')}</div>${btn('검토 근거와 사용 안내','nav','data-to="help"',true)}</div>`;}
function conceptViz(c){if(['clt','sampling','se','normal','sigmoid','correlation','pearson','detrend','stationary','difference'].includes(c.id))return `<div class="viz"><div id="concept-viz"></div>${['clt','sampling','se'].includes(c.id)?'<label>표본 크기 n = <b id="n-label">30</b><input type="range" id="clt-n" min="1" max="100" value="30"></label><p class="small muted">모평균 50, 모표준편차 20을 고정한 정규근사 그림. 원자료의 분포는 변하지 않습니다.</p>':''}${c.id==='sigmoid'?'<label>선형 예측값 z = <b id="z-label">0</b><input type="range" id="sigmoid-z" min="-6" max="6" step="0.1" value="0"></label>':''}</div>`;
 if(['maturity','cmmi','multicol','normalize','standardize','stationarize','minkowski','odds-ratio','distributions','pvalue','reject','t-test'].includes(c.id))return comparisons(c.id);return '';}
function comparisons(id){const tables={maturity:[['단계','대표 특징'],['도입','일부 부서·환경 구축'],['활용','실무 적용·예측'],['확산','전사 관리·공유'],['최적화','전략 연계·혁신']],cmmi:[['체계','수준'],['전통적 CMMI','1 초기 → 2 관리 → 3 정의 → 4 정량 관리 → 5 최적화'],['현행 공식 안내','0 Incomplete도 포함'],['ADsP 분석 성숙도','도입 → 활용 → 확산 → 최적화']],multicol:[['구분','관계','점검'],['다중공선성','설명변수 사이','VIF'],['자기상관','시차를 둔 오차 사이','DW 등']],normalize:[['변환','목적'],['정규화','범위·크기 조정'],['표준화','중심·척도 조정'],['정상화','시간에 안정적인 통계 구조']],minkowski:[['p','거리','(0,0)↔(3,4)'],['1','맨해튼','7'],['2','유클리드','5'],['∞','최대 좌표차','4']],distributions:[['분포','형태·지원','대표 용도'],['정규','좌우 대칭·실수','정규 모형·근사'],['t','대칭·두꺼운 꼬리','평균 추론'],['F','비음수·자유도 2개','분산비·ANOVA'],['χ²','비음수·자유도 1개','빈도·분산 추론']],pvalue:[['조건 (통상 규칙)','판정'],['p<α','귀무가설 기각'],['p≥α','귀무가설 기각 실패']], 't-test':[['검정','비교 대상','핵심 단위'],['일표본','한 집단과 기준값','관측값'],['독립표본','서로 다른 두 집단','집단별 관측값'],['대응표본','짝지은 두 측정','쌍별 차이']]};const rows=tables[id]||tables[id==='reject'?'pvalue':id==='standardize'||id==='stationarize'?'normalize':id==='odds-ratio'?'pvalue':'maturity'];if(id==='odds-ratio')return '<div class="notice">p=.2 → 오즈 .25 → 오즈 2배 .5 → 새 p=1/3<br>확률은 .4가 되지 않습니다.</div>';return `<div style="overflow:auto"><table class="compare">${rows.map((r,i)=>`<tr>${r.map(v=>`<${i?'td':'th'}>${esc(v)}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table></div>`;}
function drawConcept(){const el=document.getElementById('concept-viz');if(!el)return;const id=currentConcept;let paths='',labels='';if(['clt','sampling','se','normal'].includes(id)){const n=Number(document.getElementById('clt-n')?.value||1);if(document.getElementById('n-label'))document.getElementById('n-label').textContent=n;const sig=20/Math.sqrt(n);const pts=[];for(let x=0;x<=100;x+=.5){const y=Math.exp(-.5*((x-50)/sig)**2);pts.push(`${30+5*x},${190-150*y}`);}paths=`<path d="M${pts.join(' L')}" fill="none" stroke="#3182f6" stroke-width="3"/><line x1="280" x2="280" y1="20" y2="190" stroke="#9aa5b1" stroke-dasharray="4"/>`;labels=`<text x="280" y="218" text-anchor="middle">μ = 50</text><text x="35" y="25">${id==='normal'?'정규분포':'표본평균의 SE = '+sig.toFixed(2)}</text>`;}
 else if(id==='sigmoid'){let z=Number(document.getElementById('sigmoid-z')?.value||0);document.getElementById('z-label').textContent=z;let pts=[];for(let x=-6;x<=6;x+=.05)pts.push(`${30+(x+6)*41.7},${190-155/(1+Math.exp(-x))}`);let p=1/(1+Math.exp(-z));paths=`<path d="M${pts.join(' L')}" fill="none" stroke="#3182f6" stroke-width="3"/><circle cx="${30+(z+6)*41.7}" cy="${190-155*p}" r="6" fill="#087f5b"/>`;labels=`<text x="35" y="24">p = ${p.toFixed(3)}</text><text x="30" y="218">−6</text><text x="280" y="218">0</text><text x="520" y="218">6</text>`;}
 else if(['pearson','correlation'].includes(id)){for(let i=-5;i<=5;i++){paths+=`<circle cx="${280+i*43}" cy="${180-i*i*5.5}" r="5" fill="#3182f6"/>`;}labels='<text x="35" y="24">Y = X²：선형 상관 0이어도 의존 가능</text>';}
 else{let pts=[];for(let i=0;i<80;i++){const y=40+Math.sin(i*1.7)*12+Math.sin(i*.4)*8+(id==='detrend'?i:0);pts.push(`${30+i*6.3},${195-y}`);}paths=`<path d="M${pts.join(' L')}" fill="none" stroke="#3182f6" stroke-width="2"/>`;labels=`<text x="35" y="24">${id==='detrend'?'추세가 있는 계열 예시':'평균 주변에서 변동하는 계열 예시 (개념도)'}</text>`;}
 el.innerHTML=`<svg viewBox="0 0 570 235" role="img" aria-label="개념 설명 그래프"><g fill="${state.theme==='dark'?'#cbd5e1':'#526172'}" font-size="13" font-family="sans-serif"><path d="M30 35V195H540" fill="none" stroke="#9aa5b1"/>${paths}${labels}</g></svg>`;}
function formulaView(){return `<div class="eyebrow">QUICK REFERENCE</div><h1>공식·비교표 모음</h1><p class="muted">공식을 누르면 정의와 예제, 혼동 주의점을 함께 확인할 수 있습니다.</p><div class="concept-grid">${CONCEPTS.map(c=>`<button class="card concept-card" data-action="concept" data-id="${c.id}"><b>${esc(c.title)}</b><div class="formula" style="font-size:14px;width:100%;margin-bottom:0">${esc(c.formula)}</div></button>`).join('')}</div>`;}
function recordsView(){const m=stats(),sum=summary();return `<div class="eyebrow">MY LEARNING</div><h1>내 학습</h1><p class="muted">정답률은 풀이 시도 기준입니다. 같은 문제도 새 세트에서 다시 풀면 새 시도로 기록합니다.</p><div class="grid stats"><div class="card stat"><strong>${sum.unique}/350</strong><span>서로 다른 풀이 문항</span></div><div class="card stat"><strong>${sum.total?sum.rate+'%':'—'}</strong><span>전체 시도 ${sum.total}회</span></div><div class="card stat"><strong>${state.sessions.length}</strong><span>저장한 학습 세트</span></div></div><div class="card"><h2>과목별 정답률</h2>${[1,2,3].map(k=>{let n=0,g=0;for(const [id,v]of m)if(Q.get(id).subject===k){n+=v.attempts;g+=v.correct;}return `<div class="row"><span>${k}과목 · ${SUBJECTS[k]}</span><b>${n?pct(g,n)+'%':'미풀이'} <span class="muted small">${g}/${n}</span></b></div>${progress(g,n||1)}`;}).join('')}</div><h2 class="section-head">회차별 기록</h2><div class="card history-table"><table><tr><th>회차</th><th>학습 문항</th><th>시도 기준 정답률</th></tr>${[44,45,46,47,48,49,50].map(ex=>{const list=[...m].filter(([id])=>Q.get(id).exam===ex),n=list.reduce((t,[id,v])=>t+v.attempts,0),g=list.reduce((t,[id,v])=>t+v.correct,0);return `<tr><td>${ex}회</td><td>${list.length}/50</td><td>${n?pct(g,n)+'%':'—'} (${g}/${n})</td></tr>`;}).join('')}</table></div><h2 class="section-head">진행 중인 학습과 지난 세트</h2><div class="card history-table"><table><tr><th>학습 세트</th><th>생성일</th><th>진도</th><th>정답</th><th>열기</th><th>삭제</th></tr>${state.sessions.slice().reverse().map(s=>`<tr><td>${esc(s.title)}<br><span class="small muted">${s.mode} · ${esc(s.id.slice(-8))}</span></td><td>${new Date(s.created).toLocaleDateString('ko-KR')}</td><td>${answered(s)}/${s.ids.length}</td><td>${correct(s)}/${answered(s)}</td><td><button class="btn secondary tiny" data-action="resume" data-id="${esc(s.id)}">이어서 보기</button></td><td><button class="btn secondary tiny" data-action="delete-set" data-id="${esc(s.id)}">삭제</button></td></tr>`).join('')||'<tr><td colspan="6">아직 학습 기록이 없습니다.</td></tr>'}</table></div><details class="card section-head"><summary>삭제한 세트 ${state.archivedSessions.length}개 · 복원</summary><p class="small muted">목록에서 삭제해도 정오답 이력과 성적은 유지됩니다.</p>${state.archivedSessions.map(ss=>`<div class="row archive-row"><span>${esc(ss.title)} · ${answered(ss)}/${ss.ids.length}풀이</span><button class="btn secondary tiny" data-action="restore-set" data-id="${esc(ss.id)}">복원</button></div>`).join('')||'<p class="small muted">삭제한 세트가 없습니다.</p>'}</details><div class="row section-head"><h2>오답노트</h2>${btn('오답 다시 풀기','setup','data-mode="wrong"',true)}</div><p class="small muted">과거 한 번이라도 틀린 문제를 보존합니다. 최근 정답 여부는 별도로 표시합니다.</p><div class="results">${[...m].filter(([id,v])=>v.wrong>0).sort((a,b)=>b[1].last-a[1].last).map(([id,v])=>`<div class="card row"><div><b>${Q.get(id).exam}회 ${Q.get(id).no}번</b><div class="small muted">오답 ${v.wrong}회 / 시도 ${v.attempts}회 · 최근 ${v.lastCorrect?'정답':'오답'}</div></div>${btn('다시 풀기','single',`data-id="${id}"`,true)}</div>`).join('')||empty('아직 오답 기록이 없습니다.')}</div><div class="card section-head"><h2>기록 백업·복원</h2><p class="small muted">${window.adspDesktop?'기록은 이 PC의 앱 전용 저장공간에 자동 저장됩니다. 앱 폴더를 옮겨도 같은 Windows 사용자 계정에서는 기록을 이어갑니다.':'기록은 현재 브라우저와 파일 위치에 저장됩니다. 파일 이동·시크릿 모드·브라우저 초기화에 주의하세요.'} JSON 백업을 권장합니다. 외부 서버로 전송하지 않습니다.</p><div class="row start">${btn('JSON 내보내기','export')}${btn('JSON 가져오기','import','',true)}${btn('전체 기록 초기화','reset','',true)}</div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="small muted" style="margin-top:12px">가져오기는 현재 기록을 대체합니다. 적용 전 확인창을 표시합니다.</p></div>`;}
function footer(){return '<p class="bottom-note">출처: 문어CBT · 사용자 제공 기출 복원 자료. 공식 시험 원문과 구별됩니다.<br>인터넷 없이 사용 · 학습 기록은 이 브라우저에만 저장됩니다.</p>';}
function helpView(){return `<h1>사용 안내와 자료 출처</h1><div class="card long-note"><h2>설치 없이 사용하기</h2><p>HTML 파일을 내려받아 Chrome 또는 Edge로 여세요. 모든 문제·개념·기능이 한 파일 안에 있습니다. ZIP을 사용하면 먼저 압축을 풀고 HTML을 여세요.</p><p>답은 1~4 키 또는 선택지 클릭으로 제출합니다. ←/→ 키로 이동하고, 문제 번호를 눌러 바로 이동할 수 있습니다. 타이머는 문제 왼쪽 위에서 켜고 시작·일시정지·초기화합니다. 다른 화면으로 이동하면 일시정지합니다.</p><h2>별표와 이미지</h2><p>별표는 문제 보관 기능입니다. 별표 문제 메뉴에서 모아 풀 수 있습니다. 별 오른쪽 다운로드 버튼은 현재 문제 본문과 네 선택지를 PNG로 저장합니다. 정답과 해설은 이미지에 포함하지 않습니다.</p><h2>기록과 개인정보</h2><p>서버·로그인·외부 CDN을 사용하지 않습니다. HTML에서는 localStorage, Windows 앱에서는 앱 전용 파일에 학습 세트·답안·별표·개념 상태를 저장합니다. 문제별 이력은 세트별 시도를 시간순으로 모아 표시합니다. 내 학습에서 세트를 삭제하면 목록에서 숨기고 풀이 이력은 보존하며 다시 복원할 수 있습니다. 저장 공간은 브라우저마다 제한되며 이 교재의 학습 기록은 문제 HTML을 반복 저장하지 않습니다. 학습 기록 JSON은 내 학습에서 백업할 수 있습니다.</p><h2>원문 보존</h2><p>44~50회 350문항·1,400선택지·350정답·350해설을 제공받은 HTML에서 추출했습니다. 원문과 표·코드·SVG를 유지하고 외부 스크립트와 사이트 메뉴는 제외했습니다. 원문 정답 자체를 공식 정답으로 검증했다는 의미는 아닙니다. 특정 조건을 보완한 설명은 별도 검토 주석으로 표시합니다.</p><h2>추가 교육 콘텐츠 검토 근거</h2><p>개념 카드는 원문을 수정한 해설이 아닌 별도의 학습 콘텐츠입니다. 아래 원자료로 핵심 정의를 대조했습니다(2026-10-29). 외부 링크는 참고용이며 오프라인 학습에는 필요하지 않습니다.</p><ul><li><a target="_blank" rel="noopener" href="https://csrc.nist.gov/glossary/term/Central_Limit_Theorem">NIST: 중심극한정리</a></li><li><a target="_blank" rel="noopener" href="https://www.itl.nist.gov/div898/handbook/pmc/section4/pmc442.htm">NIST: 정상성·차분·변환</a></li><li><a target="_blank" rel="noopener" href="https://online.stat.psu.edu/stat504/Lesson06">Penn State: 로지스틱 회귀·오즈비</a></li><li><a target="_blank" rel="noopener" href="https://online.stat.psu.edu/stat501/Lesson04">Penn State: 선형회귀 가정</a></li><li><a target="_blank" rel="noopener" href="https://docs.oracle.com/en/database/oracle/machine-learning/oml4sql/23/dmcon/apriori.html">Oracle: Apriori·지지도·신뢰도·향상도</a></li><li><a target="_blank" rel="noopener" href="https://docs.scipy.org/doc/scipy/reference/generated/scipy.spatial.distance.minkowski.html">SciPy: 민코프스키 거리</a></li><li><a target="_blank" rel="noopener" href="https://cmmiinstitute.com/learning/appraisals/levels">CMMI Institute: 성숙도 수준</a></li></ul><p class="small muted">ADsP 4단계는 제공된 기출 복원 자료의 44회 17번·47회 17번·50회 14번 등과 대조했습니다. 공식 Data On Air 안내는 현재 조회되지 않아 그 원문을 재확인하지 못했습니다.</p></div>`;}
function updateTimer(){const s=session(),e=document.getElementById('timer-value');if(!s||!e)return;const secs=Math.floor((s.timer.elapsed+(s.timer.running?Date.now()-s.timer.since:0))/1000);e.textContent=`${String(Math.floor(secs/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;}
setInterval(()=>{if(route==='quiz')updateTimer();},500);
window.addEventListener('beforeunload',()=>pauseTimer());document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseTimer();else if(route==='quiz')render();});
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function confirmBox(title,msg,callback){const m=document.getElementById('modal');m.innerHTML=`<div class="modal-box" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${esc(title)}</h2><p>${esc(msg)}</p><div class="row start"><button class="btn" id="confirm-ok">확인</button><button class="btn secondary" id="confirm-cancel">취소</button></div></div>`;m.classList.remove('hidden');const focus=document.activeElement;const close=()=>{m.classList.add('hidden');m.innerHTML='';focus?.focus();};document.getElementById('confirm-ok').onclick=()=>{close();callback();};document.getElementById('confirm-cancel').onclick=close;document.getElementById('confirm-cancel').focus();}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action],[data-route]');if(!b||b.disabled)return;pendingNav=captureNav();if(b.dataset.route){navigate(b.dataset.route);return;}const {action,id}=b.dataset;const s=session();switch(action){case 'back':goBack();break;case 'delete-set':archiveSet(id);break;case 'restore-set':restoreSet(id);break;case 'nav':navigate(b.dataset.to);break;case 'exam':{const ex=Number(b.dataset.exam);const old=state.sessions.slice().reverse().find(s=>s.mode==='exam'&&s.title===`제${ex}회 기출 학습`);if(old){state.active=old.id;subjectFilter=0;save();navigate('quiz');}else createSet(DATA.filter(q=>q.exam===ex).map(q=>q.id),'exam',`제${ex}회 기출 학습`);break;}case 'resume':if(id)state.active=id;subjectFilter=0;save();navigate('quiz');break;case 'setup':setupMode=b.dataset.mode;navigate('setup');poolCount();break;case 'answer':answer(Number(b.dataset.selected));break;case 'jump':jump(Number(b.dataset.index));break;case 'move':move(Number(b.dataset.step));break;case 'q-filter':subjectFilter=Number(b.dataset.subject);if(subjectFilter&&Q.get(s.ids[s.index]).subject!==subjectFilter){const i=s.ids.findIndex(id=>Q.get(id).subject===subjectFilter);if(i>=0)s.index=i;}save();render();break;case 'bookmark':state.bookmark={sessionId:s.id,index:s.index,savedAt:Date.now()};save();toast('현재 문항을 북마크했습니다. 홈에서 이어서 풀 수 있습니다.');break;case 'bookmark-resume':pauseTimer();if(state.bookmark){state.active=state.bookmark.sessionId;session().index=state.bookmark.index;subjectFilter=0;save();navigate('quiz');}break;case 'reroll':setupMode=s.mode;startFromConfig(s.config||{exam:[...new Set(s.ids.map(id=>String(Q.get(id).exam)))],subject:[...new Set(s.ids.map(id=>String(Q.get(id).subject)))],count:'custom',custom:String(s.ids.length),priority:'random'});break;case 'retry':confirmBox('새 시도로 다시 풀기','기존 풀이 이력은 남기고 같은 문제 목록으로 새 학습 세트를 만듭니다.',()=>createSet(s.ids,s.mode,s.title));break;case 'star':state.stars=state.stars.includes(id)?state.stars.filter(x=>x!==id):[...state.stars,id];save();render();toast(state.stars.includes(id)?'별표 문제에 저장했습니다.':'별표를 해제했습니다.');break;case 'image':b.disabled=true;try{await exportQuestion(Q.get(id));toast('문제 PNG를 저장했습니다. 브라우저 다운로드 목록을 확인하세요.');}catch(err){toast('이미지 저장 실패: '+err.message);}finally{b.disabled=false;}break;case 'single':createSet([id],'single',`제${Q.get(id).exam}회 ${Q.get(id).no}번`);break;case 'play-stars':createSet(state.stars,'stars','별표 문제 학습');break;case 'random-stars':createSet(shuffle(state.stars),'stars','별표 문제 랜덤');break;case 'more-search':listPage++;document.getElementById('search-results').innerHTML=searchResults();break;case 'concept':openConcept(id);break;case 'concept-star':state.concepts[id].favorite=!state.concepts[id].favorite;save();render();break;case 'related':createSet(related(C.get(id)).map(q=>q.id),'related',C.get(id).title+' 관련 기출');break;case 'timer-toggle':if(s.timer.running)pauseTimer();else{s.timer.running=true;s.timer.since=Date.now();save();}render();break;case 'timer-reset':s.timer={elapsed:0,running:false,since:null};save();render();break;case 'export':pauseTimer();download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'ADSP_Learning_Backup.json');break;case 'import':document.getElementById('import-file').click();break;case 'reset':confirmBox('전체 학습 기록 초기화','모든 풀이·별표·개념·삭제한 세트 기록을 초기화합니다. 필요하면 먼저 JSON 백업을 내려받으세요.',()=>{pauseTimer();const imports=state.seedImports;state=blank();state.seedImports=imports;preserveBad=false;storageError='';save();navigate('home');toast('학습 기록을 초기화했습니다.');});break;}});
document.getElementById('theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();render();};
document.addEventListener('submit',e=>{if(e.target.id==='setup-form'){e.preventDefault();pendingNav=captureNav();startRandom(e.target);}});
document.addEventListener('input',e=>{const t=e.target;if(t.closest('#setup-form'))poolCount();if(t.id==='question-search'){searchText=t.value;listPage=0;statsCache=stats();document.getElementById('search-results').innerHTML=searchResults();}if(t.id==='concept-search'){conceptQuery=t.value;document.getElementById('concept-results').innerHTML=conceptResults();}if(t.id==='clt-n'||t.id==='sigmoid-z')drawConcept();});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='search-exam'||t.id==='search-subject'){searchExam=Number(document.getElementById('search-exam').value);searchSubject=Number(document.getElementById('search-subject').value);listPage=0;document.getElementById('search-results').innerHTML=searchResults();}if(t.id==='concept-category'||t.id==='concept-fav'){conceptFilter=document.getElementById('concept-category').value;conceptFav=document.getElementById('concept-fav').checked;document.getElementById('concept-results').innerHTML=conceptResults();}if(t.id==='concept-status'){state.concepts[currentConcept].status=Number(t.value);save();}if(t.id==='timer-enable'){state.timerEnabled=t.checked;if(!t.checked)pauseTimer();save();render();}if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>8e6)throw Error('백업은 8MB 이하만 가져올 수 있습니다.');const next=validate(JSON.parse(await t.files[0].text()));next.seedImports=[...new Set([...next.seedImports,...state.seedImports,SEED_KEY])];confirmBox('학습 기록 가져오기',`${next.sessions.length}개 학습 세트와 ${next.stars.length}개 별표로 현재 기록을 대체합니다.`,()=>{pauseTimer();state=next;preserveBad=false;save();navigate('records');toast('백업을 복원했습니다.');});}catch(err){toast('가져오기 실패: '+err.message);}t.value='';}});
document.addEventListener('keydown',e=>{const modal=document.getElementById('modal');if(!modal.classList.contains('hidden')){if(e.key==='Escape')document.getElementById('confirm-cancel').click();if(e.key==='Tab'){const focus=[...modal.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0].focus();}}return;}if(e.target.closest('input,select,textarea,[contenteditable]')||e.ctrlKey||e.altKey||e.metaKey)return;if(route==='quiz'){if(/^[1-4]$/.test(e.key)){e.preventDefault();answer(Number(e.key));}if(e.key==='ArrowRight'){e.preventDefault();move(1);}if(e.key==='ArrowLeft'){e.preventDefault();move(-1);}}});
// Canvas export: native text/table/code layout and SVG rasterization; no network or foreignObject.
async function exportQuestion(q){
 const width=1000,pad=58,content=width-2*pad,commands=[];let y=55;const measure=document.createElement('canvas').getContext('2d');
 function lines(text,w,font){measure.font=font;const result=[];for(const block of text.replace(/\r/g,'').split('\n')){let l='';for(const ch of block){if(measure.measureText(l+ch).width>w&&l){result.push(l);l=ch;}else l+=ch;}result.push(l);}return result;}
 function text(t,size=25,color='#191f28',weight=400,x=pad,w=content){const font=`${weight} ${size}px "Malgun Gothic", sans-serif`,ls=lines(t,w,font),height=size*1.65;for(const l of ls){commands.push({type:'text',text:l,x,y,font,color});y+=height;}return ls.length*height;}
 function rect(x,yy,w,h,color){commands.push({type:'rect',x,y:yy,w,h,color});}
 async function walk(el){
  if(el.nodeType===3){const t=el.textContent.trim();if(t)text(t);return;}
  const tag=el.tagName?.toLowerCase();if(['style','script'].includes(tag))return;
  if(tag==='svg'){let clone=el.cloneNode(true);if(clone.hasAttribute('viewbox')){clone.setAttribute('viewBox',clone.getAttribute('viewbox'));clone.removeAttribute('viewbox');}clone.setAttribute('xmlns','http://www.w3.org/2000/svg');const vb=(clone.getAttribute('viewBox')||'').split(/[ ,]+/).map(Number),w=Number(clone.getAttribute('width'))||vb[2]||600,h=Number(clone.getAttribute('height'))||vb[3]||300;clone.setAttribute('width',w);clone.setAttribute('height',h);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('도해 렌더링 오류'));img.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(new XMLSerializer().serializeToString(clone));});const dw=Math.min(content,w*1.6),dh=h/w*dw;commands.push({type:'image',img,x:pad+(content-dw)/2,y,w:dw,h:dh});y+=dh+25;return;}
  if(tag==='pre'){const code=el.textContent,ls=lines(code,content-32,'18px Consolas,monospace'),h=ls.length*29+30;rect(pad,y-4,content,h,'#f2f4f6');y+=15;for(const l of ls){commands.push({type:'text',text:l,x:pad+16,y,font:'18px Consolas,monospace',color:'#333d4b'});y+=29;}y+=20;return;}
  if(tag==='table'){const rows=[...el.querySelectorAll('tr')],cols=Math.max(...rows.map(r=>[...r.children].reduce((a,c)=>a+(Number(c.colSpan)||1),0))),cw=content/cols;for(const row of rows){let off=0;const cells=[...row.children].map(c=>{const w=cw*(Number(c.colSpan)||1);const a={c,w,x:pad+off,ls:lines(c.textContent.trim(),w-20,'19px "Malgun Gothic",sans-serif')};off+=w;return a;}),rh=Math.max(...cells.map(c=>c.ls.length))*30+22;for(const c of cells){rect(c.x,y,c.w-1,rh-1,c.c.tagName==='TH'?'#eaf3ff':'#f5f7f9');c.ls.forEach((l,i)=>commands.push({type:'text',text:l,x:c.x+10,y:y+12+i*30,font:'19px "Malgun Gothic",sans-serif',color:'#191f28'}));}y+=rh;}y+=22;return;}
  if(['p','li','blockquote'].includes(tag)&&!el.querySelector('svg,table,pre')){text((tag==='li'?'• ':'')+el.textContent.trim(),24);y+=9;return;}
  for(const child of el.childNodes)await walk(child);
 }
 text('ADsP · 기출 복원',22,'#3182f6',700);text(`제${q.exam}회  ${q.no}번  ·  ${q.subject}과목 ${SUBJECTS[q.subject]}`,23,'#6b7684');y+=16;
 const stem=new DOMParser().parseFromString(q.stem,'text/html');await walk(stem.body);y+=10;
 for(let i=0;i<4;i++){const start=y;y+=12;text(`${i+1}.`,24,'#3182f6',700);await walk(new DOMParser().parseFromString(q.options[i],'text/html').body);y+=18;commands.push({type:'line',x:pad,y:y-8,w:content});}
 y+=20;text('출처: 문어CBT · 사용자 제공 기출 복원 자료',17,'#6b7684');text('공식 시험 원문과 구별됩니다. 정답·해설 미포함.',17,'#6b7684');
 if(y>15000)throw Error('이미지가 너무 깁니다. 브라우저 인쇄를 이용하세요.');
 const canvas=document.createElement('canvas');canvas.width=width*2;canvas.height=Math.ceil(y+45)*2;const ctx=canvas.getContext('2d');ctx.scale(2,2);ctx.fillStyle='#fff';ctx.fillRect(0,0,width,y+45);ctx.textBaseline='top';for(const cmd of commands){if(cmd.type==='text'){ctx.fillStyle=cmd.color;ctx.font=cmd.font;ctx.fillText(cmd.text,cmd.x,cmd.y);}if(cmd.type==='rect'){ctx.fillStyle=cmd.color;ctx.fillRect(cmd.x,cmd.y,cmd.w,cmd.h);}if(cmd.type==='image')ctx.drawImage(cmd.img,cmd.x,cmd.y,cmd.w,cmd.h);if(cmd.type==='line'){ctx.strokeStyle='#e5e8eb';ctx.beginPath();ctx.moveTo(cmd.x,cmd.y);ctx.lineTo(cmd.x+cmd.w,cmd.y);ctx.stroke();}}
 const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 생성에 실패했습니다.');download(blob,`ADSP_${q.exam}_Q${String(q.no).padStart(2,'0')}.png`);
}
async function startApplication(){
 if(window.adspDesktop){try{const loaded=await window.adspDesktop.read();if(loaded.error){preserveBad=true;storageError='앱 기록 파일을 읽지 못했습니다. JSON 가져오기 또는 초기화로 복구하세요.';}else if(loaded.text){state=validate(JSON.parse(loaded.text));preserveBad=false;storageError='';}desktopReady=true;}catch(e){preserveBad=true;storageError='앱 저장 공간에 접근하지 못했습니다. 재실행하거나 JSON을 백업하세요.';}}
 installEmbeddedBackup();render();persistDesktop();
 if(window.adspDesktop)window.adspDesktop.onClosing(()=>{pauseTimer();save();window.adspDesktop.closeReady();});
}
startApplication();
